<?php $pageTitle='PHP Form Processing | StudentHub';require __DIR__.'/includes/header.php';$message='';if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$messageText=trim($_POST['message']??'');if(strlen($name)<2||!$email||strlen($messageText)<5)$message='Invalid input. Check name, email and message.';else{$entry=['name'=>$name,'email'=>$email,'message'=>$messageText,'created_at'=>date('c')];$fp=fopen(__DIR__.'/storage/submissions.csv','ab');if($fp){flock($fp,LOCK_EX);fputcsv($fp,[$entry['name'],$entry['email'],$entry['message'],$entry['created_at']]);flock($fp,LOCK_UN);fclose($fp);$message='Validated form saved to storage/submissions.csv.';}else $message='Storage file could not be opened.';}} ?><h1>PHP server-side form processing</h1><?php if($message): ?><p class="notice"><?= e($message) ?></p><?php endif; ?><form class="form" method="post"><div class="field"><label for="name">Name</label><input id="name" name="name" required minlength="2"></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required></div><div class="field"><label for="message">Message</label><textarea id="message" name="message" required minlength="5"></textarea></div><button class="button">Submit with POST</button></form><?php require __DIR__.'/includes/footer.php'; ?>
